from steps_common import S, R

R("chshnitzel", "тенджера, голям тиган, 3 дълбоки чинии, фолио или найлонов плик, тостер или фурна, преса за картофи",
  S("Сложи картофите да врат", "Обели картофите@potatoes с белачка, нарежи всеки на 4 и ги сложи в тенджера. Залей със студена вода, колкото да ги покрие с 2 пръста, и сложи {1 ч.л.} сол. Сложи на силен котлон, а като заври, намали на средно и вари 20 минути.",
    "Готови са, когато нож влиза в картоф без никакво съпротивление.", 20),
  S("Направи галета от хляба", "Сложи хляба@bread във фурна на 150° за 10 минути или го препечи в тостер, докато стане сух и хрупкав. Остави го да изстине 2 минути и го натроши на ситни трохи: с блендер или в найлонов плик, като минаваш с точилка или бутилка отгоре.",
    "Купешката галета става за същото, но домашната е по-хрупкава."),
  S("Изчукай пилешкото", "Сложи филето@chfillet на дъска. Дръж го с длан отгоре и го разрежи хоризонтално с дълъг нож на 2 тънки пържоли. Покрий ги с фолио или плик и ги чукай с дъното на тежък тиган, докато станат равномерно дебели около 1 см. Посоли ги леко от двете страни.",
    "Режи суровото пиле на отделна дъска и измий ръцете и ножа със сапун веднага след това."),
  S("Подготви три чинии за паниране", "В първата чиния сложи брашното@flour. Във втората разбий яйцата@eggs с вилица и щипка сол, докато жълтъкът и белтъкът се смесят. В третата сложи галетата. Подреди ги една до друга в този ред."),
  S("Панирай шницелите", "Вземи пържола и я овалий в брашното, като изтупаш излишното. После я потопи в яйцата от двете страни и я остави да се отцеди 2 секунди. Накрая я сложи в галетата и притисни с длан, за да полепне навсякъде. Остави я на чиста чиния и повтори с останалите.",
    "Ползвай едната ръка за сухите чинии, а другата за яйцата: така пръстите не се облепват."),
  S("Изпържи до златисто", "Налей олиото@oil в голям тиган и го загрей на средна степен 2–3 минути. Сложи 2 шницела (не повече, иначе олиото изстива) и пържи 3–4 минути, докато долу е златисто. Обърни с шпатула и пържи още 3–4 минути. Извади ги върху кухненска хартия.",
    "Проба дали олиото е готово: пусни троха галета. Ако веднага зацвърчи, е готово.", 7),
  S("Направи пюрето", "Изцеди картофите и ги върни в топлата тенджера. Затопли млякото@milk (1 минута в микровълнова или в малко тенджерче) и го налей при тях. Смачкай с преса или вилица, докато няма бучки. Опитай и посоли."),
)

R("porkshnitzel", "тенджера, голям тиган, 3 дълбоки чинии, фолио или плик, купа",
  S("Сложи картофите да врат", "Обели картофите@potatoes и ги разрежи наполовина. Сложи ги в тенджера със студена вода и {1 ч.л.} сол. Като заври, намали на средно и вари 20 минути, докато нож влиза лесно.", None, 20),
  S("Галета и месо", "Изсуши хляба@bread в тостер или фурна и го натроши на ситни трохи. Нарежи месото@porkleg на пържоли около 1 см, срещу посоката на влакната. Покрий ги с фолио и ги изчукай с дъното на тиган до около 0,5 см. Посоли ги от двете страни.",
    "Влакната на месото са като тънки линии. Режи напреко на тях, така месото става по-крехко."),
  S("Панирай", "Подреди 3 чинии: брашно@flour, разбити с вилица яйца@eggs, галета. Овалий всяка пържола първо в брашното и изтупай излишното. Потопи я в яйцата, остави я да се отцеди и я притисни в галетата от двете страни."),
  S("Изпържи", "Загрей олиото@oil в тиган на средна степен 2–3 минути. Пържи по 2 шницела наведнъж по 4 минути от страна, докато са златисти. Извади ги върху кухненска хартия.",
    "Свинското трябва да е бяло отвътре. Ако не си сигурен, разрежи един шницел в средата.", 8),
  S("Зелевата салата", "Махни външните листа и сърцевината на зелето@cabbage и го нарежи възможно най-тънко. Посоли с {0.5 ч.л.} сол и го мачкай с ръце 1 минута, докато пусне малко сок и омекне. Овкуси с {1 с.л.} оцет и {1 с.л.} олио. Изцеди картофите и сервирай всичко заедно."),
)

R("printsesi", "тава, хартия за печене, купа, ренде, лъжица",
  S("Подготви фурната и каймата", "Включи фурната на 200°. В купа сложи каймата@mince, яйцето@eggs, {0.5 ч.л.} сол и {1 ч.л.} чубрица и ги омеси с ръка или вилица 1 минута, докато се смесят равномерно."),
  S("Намажи филиите", "Нареди филиите@bread в тава, покрита с хартия за печене. С лъжица разстели тънък слой кайма (колкото 2–3 мм) върху всяка филия, до самите краища и ъгли.",
    "Ако оставиш непокрити краища, те изгарят, докато каймата се изпече."),
  S("Изпечи", "Сложи тавата на средната решетка и пеки 12–15 минути. Каймата трябва да смени цвета си от розов на сивокафяв навсякъде.", None, 14),
  S("Кашкавалът", "Настържи кашкавала@kashkaval. Извади тавата с ръкавица, поръси всяка принцеса и върни във фурната за още 3 минути, докато се разтопи.", None, 3),
  S("Салатата", "Докато се пекат, нарежи доматите@tomato и краставиците@cucumber на кубчета, посоли и сервирай с принцесите."),
)

R("pyrjeni", "тиган, дълбока чиния, вилица, шпатула, кухненска хартия",
  S("Яйчената смес", "В дълбока чиния разбий с вилица яйцата@eggs, млякото@milk и щипка сол, докато сместа стане еднородно жълта, без нишки белтък."),
  S("Загрей олиото", "Налей олиото@oil в тиган и го загрей на средна степен 2 минути.",
    "Проба: пусни капка от яйчената смес. Ако веднага се надуе и зацвърчи, олиото е готово."),
  S("Потопи и пържи", "Потопи филия@bread в сместа за 2–3 секунди от едната страна, обърни я за още 2–3 секунди и я сложи в тигана. Пържи 2 минути, докато е златиста, обърни с шпатула и пържи още 2 минути. Извади върху хартия.",
    "Не държи филията по-дълго в яйцата, иначе се разкисва и се къса.", 4),
  S("Сервирай", "Нарежи сиренето@sirene на парчета, а доматите@tomato и краставиците@cucumber на салата. Сервирай филийките топли."),
)

R("panagyurski", "широка тенджера, малка чашка, решетъчна лъжица, малко тиганче или купичка, преса за чесън",
  S("Подготви млякото", "Обели чесъна@garlic и го смачкай с преса или го настържи. Смеси го с киселото мляко@yogurt и щипка сол. Разпредели млякото в дълбоки чинии, за да се темперира, докато правиш яйцата."),
  S("Подготви водата", "В широка тенджера налей вода около 8 см и сложи {1 с.л.} оцет. Заври я, после намали котлона, докато по дъното се появяват само малки мехурчета (тихо къкрене).",
    "Ако водата кипи бурно, разкъсва белтъка на нишки."),
  S("Поширай яйцата", "Счупи едно яйце@eggs в малка чашка. Доближи чашката до водата и плъзни яйцето внимателно вътре. Пусни още 1–2 така. Вари 3 минути, после извади всяко с решетъчна лъжица и го остави да се отцеди за секунда.",
    "Оцетът помага белтъкът бързо да се стегне около жълтъка. Готовото яйце е бяло отвън и меко, когато го побутнеш.", 3),
  S("Подреди", "Нареди по 2 яйца в чиния върху киселото мляко. Повтори с останалите яйца."),
  S("Маслото с червен пипер", "Разтопи маслото@butter в тиганче на слаба степен. Махни го от котлона и веднага разбъркай {1 ч.л.} червен пипер. Полей яйцата и сервирай с хляб@bread за топене."),
)

R("lentilsalad", "тенджера, цедка, голяма купа, дъска, нож",
  S("Свари лещата", "Изплакни лещата@lentils в цедка. Сложи я в тенджера с много вода (поне 3 пъти повече от лещата) и заври. Намали на средно и вари 18–20 минути, като опитваш от 15-ата минута: трябва да е мека, но да не се разпада.",
    "Посоли водата чак накрая: солта в началото забавя омекването.", 19),
  S("Охлади лещата", "Изцеди лещата и я залей за 10 секунди със студена вода, за да спре да се готви. Разстели я в купа да изстине напълно."),
  S("Нарежи зеленчуците", "Нарежи доматите@tomato и краставиците@cucumber на кубчета около 1 см. Нарежи лука@onion възможно най-ситно, защото суровият лук на едро е твърде силен."),
  S("Смеси и овкуси", "Смеси лещата със зеленчуците. Полей със зехтина@oliveoil и сока от лимона@lemon, посоли с {0.5 ч.л.} сол и разбъркай. Натроши сиренето@sirene отгоре."),
)

R("palachinkiizvara", "тиган около 24 см, голяма купа, бъркалка, черпак, шпатула",
  S("Тестото", "В купа счупи яйцата@eggs, налей млякото@milk и сложи щипка сол. Добавяй брашното@flour по малко, като бъркаш с бъркалка, докато тестото стане гладко като течна сметана. Остави го 10 минути.",
    "Почивката прави палачинките по-еластични и не се късат при обръщане.", 10),
  S("Загрей тигана", "Загрей тиган на средна степен 2 минути. Намажи го с капка олио@oil с кухненска хартия: трябва да лъщи, без да има локвичка."),
  S("Изпечи палачинките", "Налей черпак тесто в средата на тигана и веднага го завърти във всички посоки, за да се разлее тънко по цялото дъно. Пеки около 1 минута, докато краищата започнат да се отлепят и долу има кафяви петна. Обърни с шпатула и пеки още 30 секунди. Трупай готовите в чиния.",
    "Първата палачинка често не става: това е нормално, тиганът още се загрява."),
  S("Плънката", "В купа смеси изварата@curd със захарта@sugar и {0.5 ч.л.} канела с лъжица, докато стане кремообразна."),
  S("Напълни и сгъни", "Сложи 2 лъжици плънка в единия край на палачинката, разстели я и сгъни палачинката на две, после още веднъж на триъгълник. Сервирай веднага или ги затопли 1 минута в тигана."),
)

R("omlethunka", "тиган около 24 см, купа, ренде, шпатула",
  S("Подготви", "Нарежи шунката@ham на малки кубчета. Настържи кашкавала@kashkaval на едро ренде."),
  S("Разбий яйцата", "В купа разбий с вилица яйцата@eggs, млякото@milk и щипка сол около 30 секунди, докато се появят малки мехурчета."),
  S("Първият омлет", "Разтопи половината масло@butter*0.5 в тигана на средна степен. Изсипи половината яйчена смес и разпредели половината шунка отгоре. Не бъркай: остави да се стегне около 3 минути, докато отгоре е почти сух.",
    "Ако краищата се стягат, а средата е течна, повдигни ръба с шпатула и наклони тигана, за да изтече сурово яйце отдолу.", 3),
  S("Сгъни", "Поръси половината кашкавал, повдигни единия край на омлета с шпатулата и го сгъни на две. Плъзни го в чиния."),
  S("Вторият омлет", "Повтори със останалото масло@butter*0.5, яйца и шунка. Сервирай с нарязани домати@tomato и хляб@bread."),
)

R("porkpure", "тенджера, тиган, преса за картофи, преса за чесън",
  S("Картофите", "Обели картофите@potatoes, нарежи ги на 4 и ги сложи в тенджера със студена вода и {1 ч.л.} сол. От завирането вари 20 минути.", None, 20),
  S("Месото", "Нарежи месото@porkleg на медальони (кръгли парчета) около 2 см дебели. Подсуши ги с хартия, посоли и поръси с пипер от двете страни."),
  S("Изпечи медальоните", "Загрей олиото@oil в тиган на силна степен 2 минути, докато леко запуши. Нареди медальоните с разстояние помежду им и не ги мести 4 минути, за да хванат кафява коричка. Обърни и пеки още 4 минути. Остави ги 3 минути в чиния.",
    "Готово е, когато месото е бяло отвътре, с най-много лек розов оттенък в самия център.", 8),
  S("Пюрето", "Изцеди картофите. Добави маслото@butter, топлото мляко@milk и смачкания чесън@garlic и смачкай до гладко пюре. Посоли на вкус."),
)

R("stuffedpot", "тава, лъжица, купа, ренде, кухненска ръкавица",
  S("Изпечи картофите цели", "Включи фурната на 200°. Изтъркай картофите@potatoes под водата с четка (кората остава), подсуши ги и ги набоди с вилица на 4–5 места. Нареди ги в тава и ги пеки 45–50 минути.",
    "Готови са, когато нож влиза в средата без съпротива.", 48),
  S("Издълбай", "Извади ги с ръкавица и ги остави 5 минути. Разрежи всеки по дължина наполовина и издълбай вътрешността с лъжица в купа, като оставиш около 0,5 см до кората, за да не се скъса."),
  S("Плънката", "Нарежи шунката@ham на кубчета и настържи кашкавала@kashkaval. Смачкай картофената вътрешност с маслото@butter, шунката, половината кашкавал, {0.5 ч.л.} сол и пипер. Напълни отново корите с лъжица."),
  S("Запечи", "Поръси с останалия кашкавал и запечи 10 минути, докато отгоре стане златисто. Сервирай с кисело мляко@yogurt.", None, 10),
)

R("fishpure", "тенджера, голям тиган, широка шпатула, преса за картофи",
  S("Картофите", "Обели картофите@potatoes, нарежи ги на 4 и ги свари в подсолена вода 20 минути от завирането.", None, 20),
  S("Подготви рибата", "Изплакни пъстървата@trout и я подсуши много добре с хартия отвътре и отвън. Посоли я и я поръси с пипер.",
    "Сухата риба не пръска и хваща хрупкава кожа."),
  S("Изпържи рибата", "Разтопи половината масло@butter*0.5 в голям тиган на средна към силна степен, докато спре да се пени. Сложи рибата и я пържи 5 минути, без да я местиш. Обърни внимателно с широка шпатула и пържи още 5 минути.", None, 10),
  S("Пюрето и сервиране", "Изцеди картофите и ги смачкай с останалото масло@butter*0.5 и топлото мляко@milk. Сервирай рибата с пюрето и резенчета лимон@lemon."),
)

R("mackerelgrill", "грил тиган или обикновен тиган, кухненска хартия, ножица, голяма купа, ренде",
  S("Подготви рибата", "Ако скумрията@mackerel е замразена, размрази я в хладилника от предната вечер. Ако не е почистена, срежи корема с ножица, извади вътрешностите и изплакни. Подсуши я много добре с хартия и я посоли отвътре и отвън."),
  S("Загрей тигана", "Намажи грил тигана с капка олио@oil*0.25 с хартия и го загрей на силна степен 3 минути, докато е много горещ."),
  S("Изпечи", "Сложи рибата и не я пипай 6–7 минути, докато кожата се отлепи сама от тигана. Обърни внимателно и пеки още 6 минути.",
    "Ако рибата залепва, още не е готова за обръщане. Изчакай още минута.", 13),
  S("Салатата", "Нарежи зелето@cabbage много тънко, настържи моркова@carrot. Посоли и мачкай с ръце 1 минута. Овкуси с олиото@oil*0.75, {1 с.л.} оцет и сока от лимона@lemon. Сервирай рибата със салатата."),
)
